namespace Outer {
    int lookup_id = 1; // 3. Namespace scope

    class ScopeDemo {
        int lookup_id = 2; // 2. Class scope
    public:
        void demo_unqual_lookup() {
            int lookup_id = 3; // 1. Local scope (Innermost)

            // Unqualified Name Lookup starts here (innermost scope):
            // 1. Searches local scope (found: 3)
            // 2. Searches class scope
            // 3. Searches enclosing namespace scope
            // 4. Searches global scope

            lookup_id;      // Resolves to 3 (Local)
            this->lookup_id; // Resolves to 2 (Class member)
            Outer::lookup_id; // Resolves to 1 (Namespace member)
            ::lookup_id;    // Requires global 'lookup_id' declaration
        }
    };
}

int lookup_id = 0; // 4. Global scope (Farthest scope)
